import type {RolePlayNode, RolePlayScenario} from '../../types/interactiveLab';
import type {HighSchoolGrade} from '../../types/lesson';

interface RolePlaySeed {
  id: string; // R01..R30
  unitId: string;
  grade: HighSchoolGrade;
  unitNumber: number;
  titleEn: string;
  titleVi: string;
  settingVi: string;
  studentRoleVi: string;
  npcName: string;
  npcRole: string;
  objectiveVi: string;
  vocab: [string, string, string, string];
  structure: string;
  // Turn 1
  t1En: string;
  t1Vi: string;
  c1A: {en: string; tag: string; fb: string}; // Branch A (proactive/detailed)
  c1B: {en: string; tag: string; fb: string}; // Branch B (cautious/questioning)
  // Turn 2 Branch A & Branch B (distinct meaningful branching!)
  t2AEn: string;
  t2AVi: string;
  c2A1: {en: string; tag: string; fb: string};
  c2A2: {en: string; tag: string; fb: string};
  t2BEn: string;
  t2BVi: string;
  c2B1: {en: string; tag: string; fb: string};
  c2B2: {en: string; tag: string; fb: string};
  // Turn 3
  t3En: string;
  t3Vi: string;
  c3A: {en: string; tag: string; fb: string};
  c3B: {en: string; tag: string; fb: string};
  // Turn 4
  t4En: string;
  t4Vi: string;
  c4A: {en: string; tag: string; fb: string};
  c4B: {en: string; tag: string; fb: string};
  // Turn 5 (Closing exchange)
  t5En: string;
  t5Vi: string;
  c5A: {en: string; tag: string; fb: string};
  c5B: {en: string; tag: string; fb: string};
  // Distinct ending summaries
  endGreatVi: string;
  endGoodVi: string;
}

function buildScenario(s: RolePlaySeed): RolePlayScenario {
  const nodes: RolePlayNode[] = [
    {
      id: 't1',
      turnNumber: 1,
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: s.t1En,
      npcLineVi: s.t1Vi,
      vocabHints: [s.vocab[0], s.vocab[1]],
      structureHintEn: s.structure,
      choices: [
        {id: 'c1a', textEn: s.c1A.en, registerTag: s.c1A.tag, feedbackVi: s.c1A.fb, scoreDelta: 2, nextNodeId: 't2a'},
        {id: 'c1b', textEn: s.c1B.en, registerTag: s.c1B.tag, feedbackVi: s.c1B.fb, scoreDelta: 1, nextNodeId: 't2b'},
      ],
    },
    {
      id: 't2a',
      turnNumber: 2,
      branchTag: 'Nhánh A · Chủ động đề xuất',
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: s.t2AEn,
      npcLineVi: s.t2AVi,
      vocabHints: [s.vocab[1], s.vocab[2]],
      structureHintEn: s.structure,
      choices: [
        {id: 'c2a1', textEn: s.c2A1.en, registerTag: s.c2A1.tag, feedbackVi: s.c2A1.fb, scoreDelta: 2, nextNodeId: 't3'},
        {id: 'c2a2', textEn: s.c2A2.en, registerTag: s.c2A2.tag, feedbackVi: s.c2A2.fb, scoreDelta: 1, nextNodeId: 't3'},
      ],
    },
    {
      id: 't2b',
      turnNumber: 2,
      branchTag: 'Nhánh B · Trao đổi làm rõ',
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: s.t2BEn,
      npcLineVi: s.t2BVi,
      vocabHints: [s.vocab[0], s.vocab[2]],
      structureHintEn: s.structure,
      choices: [
        {id: 'c2b1', textEn: s.c2B1.en, registerTag: s.c2B1.tag, feedbackVi: s.c2B1.fb, scoreDelta: 2, nextNodeId: 't3'},
        {id: 'c2b2', textEn: s.c2B2.en, registerTag: s.c2B2.tag, feedbackVi: s.c2B2.fb, scoreDelta: 1, nextNodeId: 't3'},
      ],
    },
    {
      id: 't3',
      turnNumber: 3,
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: s.t3En,
      npcLineVi: s.t3Vi,
      vocabHints: [s.vocab[2], s.vocab[3]],
      structureHintEn: s.structure,
      choices: [
        {id: 'c3a', textEn: s.c3A.en, registerTag: s.c3A.tag, feedbackVi: s.c3A.fb, scoreDelta: 2, nextNodeId: 't4'},
        {id: 'c3b', textEn: s.c3B.en, registerTag: s.c3B.tag, feedbackVi: s.c3B.fb, scoreDelta: 1, nextNodeId: 't4'},
      ],
    },
    {
      id: 't4',
      turnNumber: 4,
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: s.t4En,
      npcLineVi: s.t4Vi,
      vocabHints: [s.vocab[0], s.vocab[3]],
      structureHintEn: s.structure,
      choices: [
        {id: 'c4a', textEn: s.c4A.en, registerTag: s.c4A.tag, feedbackVi: s.c4A.fb, scoreDelta: 2, nextNodeId: 't5'},
        {id: 'c4b', textEn: s.c4B.en, registerTag: s.c4B.tag, feedbackVi: s.c4B.fb, scoreDelta: 1, nextNodeId: 't5'},
      ],
    },
    {
      id: 't5',
      turnNumber: 5,
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: s.t5En,
      npcLineVi: s.t5Vi,
      vocabHints: [s.vocab[1], s.vocab[3]],
      structureHintEn: s.structure,
      choices: [
        {id: 'c5a', textEn: s.c5A.en, registerTag: s.c5A.tag, feedbackVi: s.c5A.fb, scoreDelta: 2, nextNodeId: 'end_great'},
        {id: 'c5b', textEn: s.c5B.en, registerTag: s.c5B.tag, feedbackVi: s.c5B.fb, scoreDelta: 1, nextNodeId: 'end_good'},
      ],
    },
    {
      id: 'end_great',
      turnNumber: 6,
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: 'Thank you for such a thoughtful and well-structured conversation! Everything is clearly agreed.',
      npcLineVi: 'Cảm ơn bạn vì cuộc trao đổi sâu sắc, rõ ràng! Mọi kế hoạch đã được thống nhất trọn vẹn.',
      vocabHints: [...s.vocab],
      structureHintEn: s.structure,
      isEnd: true,
      endSummaryVi: s.endGreatVi,
    },
    {
      id: 'end_good',
      turnNumber: 6,
      npcName: s.npcName,
      npcRole: s.npcRole,
      npcLineEn: 'Thanks for sharing your ideas! We have a workable plan and can refine the details next time.',
      npcLineVi: 'Cảm ơn bạn đã chia sẻ ý kiến! Chúng ta đã có phương án khả thi và có thể hoàn thiện thêm chi tiết sau.',
      vocabHints: [...s.vocab],
      structureHintEn: s.structure,
      isEnd: true,
      endSummaryVi: s.endGoodVi,
    },
  ];

  return {
    id: s.id,
    unitId: s.unitId,
    grade: s.grade,
    unitNumber: s.unitNumber,
    titleEn: s.titleEn,
    titleVi: s.titleVi,
    settingVi: s.settingVi,
    studentRoleVi: s.studentRoleVi,
    npcName: s.npcName,
    objectiveVi: s.objectiveVi,
    startNodeId: 't1',
    nodes,
    provenance: 'teacher_authored_interactive',
  };
}

