export const ROLEPLAY_SCENARIOS: RolePlayScenario[] = SEEDS.map(buildScenario);

export function getRolePlayById(id: string): RolePlayScenario | undefined {
  return ROLEPLAY_SCENARIOS.find((r) => r.id === id);
}

export function getRolePlayByUnit(unitId: string): RolePlayScenario | undefined {
  return ROLEPLAY_SCENARIOS.find((r) => r.unitId === unitId);
}
